using EngineQuestion = std::variant<LinkActivation>;
template <typename T>
struct EngineQuestionAnswer;
template <>
struct EngineQuestionAnswer<LinkActivation> {
  using Type = LinkNavigationAnswer;
};
inline void Write(WireWriter& writer, const EngineQuestion& value) {
  writer.WriteVarint(value.index());
  std::visit([&writer](const auto& member) { Write(writer, member); }, value);
}
inline bool Read(WireReader& reader, EngineQuestion& value) {
  switch (reader.ReadTag()) {
    case 0: {
      LinkActivation member;
      if (!Read(reader, member)) return false;
      value = std::move(member);
      return true;
    }
    default:
      reader.Fail();
      return false;
  }
}

// One whole message: a union or the registration, encoded on its own.
template <typename T>
std::vector<uint8_t> Encode(const T& message) {
  WireWriter writer;
  Write(writer, message);
  return writer.Take();
}

// One whole message decoded, or nothing when its bytes do not decode or
// run past it.
template <typename T>
std::optional<T> Decode(const uint8_t* data, size_t length) {
  WireReader reader(data, length);
  T message{};
  if (!Read(reader, message) || !reader.ok() || !reader.AtEnd()) return std::nullopt;
  return message;
}

